func _poolAppendChar(tls *libc.TLS, pool uintptr, c TXML_Char) (r uint8) {
	var v1, v2 uintptr
	_, _ = v1, v2
	if (*TSTRING_POOL)(unsafe.Pointer(pool)).Fptr == (*TSTRING_POOL)(unsafe.Pointer(pool)).Fend && !(_poolGrow(tls, pool) != 0) {
		return libc.BoolUint8(Mfalse != 0)
	}
	v2 = pool + 24
	v1 = *(*uintptr)(unsafe.Pointer(v2))
	*(*uintptr)(unsafe.Pointer(v2)) = *(*uintptr)(unsafe.Pointer(v2)) + 1
	**(**TXML_Char)(__ccgo_up(v1)) = c
	return libc.BoolUint8(Mtrue != 0)
}

func _poolAppendChars(tls *libc.TLS, pool uintptr, s uintptr, len1 Tsize_t) (r uint8) {

	if len1 > libc.Uint64FromUint64(0xffffffffffffffff)/libc.Uint64FromInt64(1) {
		return libc.BoolUint8(Mfalse != 0)
	}
	if !(_poolGrowUntil(tls, pool, len1) != 0) {
		return libc.BoolUint8(Mfalse != 0)
	}
	libc.Xmemcpy(tls, (*TSTRING_POOL)(unsafe.Pointer(pool)).Fptr, s, len1*uint64(1))
	**(**uintptr)(__ccgo_up(pool + 24)) += uintptr(len1)
	return libc.BoolUint8(Mtrue != 0)
}

